import java.util.*;class Solution{public int shortestDistance(int[][]g){int m=g.length,n=g[0].length,bc=0;int[][]sum=new int[m][n],reach=new int[m][n];int[][]d={{1,0},{-1,0},{0,1},{0,-1}};for(int i=0;i<m;i++)for(int j=0;j<n;j++)if(g[i][j]==1){bc++;Queue<int[]>q=new ArrayDeque<>();q.add(new int[]{i,j});boolean[][]v=new boolean[m][n];int dist=0;while(!q.isEmpty()){int z=q.size();dist++;while(z-->0){int[]p=q.remove();for(int[]x:d){int a=p[0]+x[0],b=p[1]+x[1];if(a>=0&&b>=0&&a<m&&b<n&&!v[a][b]&&g[a][b]==0){v[a][b]=true;sum[a][b]+=dist;reach[a][b]++;q.add(new int[]{a,b});}}}}}int ans=Integer.MAX_VALUE;for(int i=0;i<m;i++)for(int j=0;j<n;j++)if(g[i][j]==0&&reach[i][j]==bc)ans=Math.min(ans,sum[i][j]);return ans==Integer.MAX_VALUE?-1:ans;}}
